#include <stdio.h>
/* ex03：波特率与比特率——调制方式决定「一个码元载几个比特」
 * 比特率 = 波特率 × log2(V)
 *   ASK / FSK / 2-PSK : 1 bit/码元
 *   4-PSK (QPSK)      : 2 bit/码元
 *   16-QAM            : 4 bit/码元
 *   64-QAM            : 6 bit/码元
 * 这是 408 最常考的一组换算，也解释了「为什么 4G 要用高阶调制」。*/
typedef struct {
    const char *name;
    int         bits;      /* 每码元比特数 = log2(星座点数) */
    int         points;    /* 星座点数 */
} Mod;

int main(void) {
    double baud = 2400.0;              /* 码元率 2400 Baud */
    Mod mods[] = {
        {"ASK",      1,  2},
        {"FSK",      1,  2},
        {"BPSK",     1,  2},
        {"QPSK",     2,  4},
        {"16-QAM",   4, 16},
        {"64-QAM",   6, 64}
    };
    int n = (int)(sizeof(mods) / sizeof(mods[0]));

    printf("码元率 = %.0f Baud（每秒 2400 个码元）\n", baud);
    printf("------------------------------------------------------\n");
    printf("%-10s %-14s %-16s %s\n", "调制方式", "星座点数", "比特率(bps)", "每码元比特");
    for (int i = 0; i < n; i++) {
        double bps = baud * mods[i].bits;
        printf("%-10s %-14d %-16.0f %d\n", mods[i].name, mods[i].points, bps, mods[i].bits);
    }
    printf("------------------------------------------------------\n");
    printf("结论：带宽（波特率）不变时，靠提高调制阶数就能提升比特率 ——\n");
    printf("      代价是星座点变密，抗噪能力下降（同样噪声下误码率上升）。\n");
    printf("      这就是「WiFi 信号差时自动降速」的根本原因：\n");
    printf("      从 64-QAM 退到 QPSK，宁可慢也要保证不误码。\n");
    return 0;
}
